<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {charity,asset,path,fmt} from '../data'
import {session,openModal,logout} from '../session'
import Icon from '../components/Icon.vue'
import Coin from '../components/Coin.vue'
const route=useRoute(),category=ref("aiQuant.templates.filterAll"),slide=ref(0),query=ref(''),activeTab=ref("copytrade.tabs.leaderboard"),filters=ref(false),coin=ref('USDT'),network=ref('ETH'),amount=ref(''),address=ref(''),hash=ref(''),receipt=ref(null),message=ref(''),selected=ref(null)
const section=computed(()=>route.params.section)
const banners=[["content.ui.weCareForEveryChildCaughtInTheDevastation",'409d2b38d3103f4f.jpg'],["content.ui.weHelpEndHunger",'474d7ad6e890e265.jpg'],["content.ui.weBringComputersAndEthernetNetworksToEveryCorner",'924f557a9a47fa15.jpg'],["content.ui.weProvideHopeInTimesOfDisaster",'bdb62b7ed08ba2ce.jpg'],["content.ui.weInvestInTheEducationalFutureOfCountriesIn",'d9bfaf5ec8022daa.webp'],["content.ui.weHelpPeopleWithDisabilitiesStartANewLife",'d6c929ab13ae70e6.jpg']]
const quotes=[['ETH',1725.7971,1,1000],['USDC',1.0111413,1000,1e9],['BTC',61307.0101,.1,1000],['USDT',1.01,3000,1e8],['SOL',72.5786,100,5000]],filteredQuotes=computed(()=>quotes.filter(q=>category.value==="aiQuant.templates.filterAll"||category.value===q[0]))
const titles={about:"footer.ui.aboutNewquantcapital",privacy:"common.privacyPolicy",content:"footer.ui.termsOfService",agreement:"common.userAgreement",'risk-disclosure':"common.riskDisclosure",'regulatory-information':"common.regulatoryInformation",'help-center':"common.helpCenter",profile:"common.profile",kyc:"content.ui.identityVerification",messages:"common.announcements"}
watch(()=>route.fullPath,()=>{category.value="aiQuant.templates.filterAll";message.value='';selected.value=null;amount.value='';address.value='';hash.value='';receipt.value=null})
function receiptChange(event){const f=event.target.files?.[0];message.value='';if(f&&!['image/png','image/jpeg'].includes(f.type)){message.value="content.ui.selectAPngOrJpegImage";receipt.value=null;return}if(f?.size>10*1024*1024){message.value="content.ui.imageMustNotExceed10Mb";receipt.value=null;return}receipt.value=f?.name||null}
function submitFunds(){message.value='';if(!Number.isFinite(Number(amount.value))||Number(amount.value)<=0){message.value="aiQuant.quantFund.subscribe.errorAmountInvalid";return}if(section.value==='deposit'&&!receipt.value){message.value="deposit.voucher.screenshotLabel";return}if(section.value==='withdraw'&&!address.value.trim()){message.value="assets.withdraw.error.addressRequired";return}session.orders.push({name:section.value==='deposit'?"content.ui.demoDepositRequest":"content.ui.demoWithdrawalRequest",amount:amount.value,symbol:coin.value});message.value="content.ui.localDemoCompletedNoDataOrFundsWereSent";amount.value=''}
</script>
<template>
<template v-if="section==='charity'"><section class="charity-banner"><img :src="asset(banners[slide][1])" :alt="$t(banners[slide][0])"/><h1>{{ $t(banners[slide][0]) }}</h1><div class="carousel-dots"><button v-for="(b,i) in banners" :key="b[0]" :class="{active:slide===i}" :aria-label="$t('charity.slideLabel',{index:i+1,title:$t(b[0])})" :aria-pressed="slide===i" @click="slide=i"></button></div></section><section class="charity-intro"><h2 class="section-heading">{{ $t("charity.narrative.title") }}</h2><p>{{ $t("content.ui.connectGenerosityWithMeaningfulChangeAndBringHopeTo") }}</p></section><section class="container section-pad"><div class="section-row"><h2 class="section-heading">{{ $t("charity.donations.columns.project") }}</h2><span class="muted">{{ $t("charity.stats.title") }}</span></div><div class="three-cols"><article v-for="(p,i) in charity" :key="p[0]" class="charity-card"><img :src="asset(p[1])" :alt="$t(p[0])" loading="lazy"/><div><h3>{{ $t(p[0]) }}</h3><div class="summary-line"><small>{{ $t("charity.campaigns.raisedLabel") }}</small><strong>{{ $t(p[3]) }}{{ $t(" USDT") }}</strong></div><div class="progress"><span :style="{width:p[2]+'%'}"></span></div><div class="summary-line"><small>{{ $t("charity.campaigns.targetLabel") }}{{ $t(p[4]) }}{{ $t(" USDT") }}</small><small>{{ $t(p[2]) }}%</small></div><p class="mini-label" style="margin-top:12px">{{ $t("charity.stats.peopleHelped") }}{{ $t(p[5]) }}</p><button class="primary-button wide-button" @click="openModal('donate',&quot;charity.donations.columns.project&quot;,{name:p[0],symbol:'USDT',min:1})">{{ $t("charity.campaigns.donate") }}</button></div></article></div></section><section class="container section-pad section-bordered"><div class="two-cols"><div><small class="mini-label">{{ $t("charity.stats.totalRaised") }}</small><p class="metric section-gap">70,777,391 <small>{{ $t("USDT") }}</small></p></div><div><small class="mini-label">{{ $t("charity.stats.peopleHelped") }}</small><p class="metric section-gap">1,314,922 <small>{{ $t("promotion.progress.unit.REFERRAL") }}</small></p></div></div><div class="card section-gap"><h2>{{ $t("charity.donations.label") }}</h2><p class="empty">{{ $t("charity.donations.empty.desc") }}</p><p class="mini-label">{{ $t("content.ui.sourceFiguresAreASnapshotLocalDonationsAreDemonstrations") }}</p></div></section><section class="container section-pad section-bordered"><h2 class="section-heading">{{ $t("charity.howItWorks.title") }}</h2><div class="four-cols section-gap"><div v-for="(s,i) in [&quot;charity.donations.columns.project&quot;,&quot;charity.donate.amountLabel&quot;,&quot;charity.donate.confirm.submit&quot;,&quot;charity.narrative.highlights.2.title&quot;]" :key="s"><p class="metric">0{{ $t(i+1) }}</p><h3 style="margin-top:20px">{{ $t(s) }}</h3></div></div></section></template>
<template v-else-if="section==='c2c'"><div class="page-wrap"><nav class="subnav"><RouterLink v-for="[label,id] in [[&quot;assets.convert.to&quot;,'buy'],[&quot;assets.convert.from&quot;,'sell'],[&quot;c2c.nav.orders&quot;,'orders'],[&quot;c2c.nav.paymentAccounts&quot;,'accounts']]" :key="id" :to="path('/c2c/'+id)">{{ $t(label) }}</RouterLink></nav><div class="summary-line"><div><h1 class="page-title">{{ $t("c2c.pageTitle") }}</h1><p class="page-desc">{{ $t("c2c.subtitle") }}</p></div><button class="secondary-button" @click="openModal('info',&quot;c2c.merchant.apply&quot;,{description:&quot;content.ui.merchantReviewIsNotConnectedInThisLocalDemo&quot;})">{{ $t("c2c.merchant.apply") }}</button></div><div v-if="['orders','accounts'].includes(route.params.id)" class="card section-gap"><h2>{{ $t(route.params.id==='orders'?"c2c.nav.orders":"c2c.nav.paymentAccounts") }}</h2><div class="empty">{{ $t("content.ui.no") }}{{ $t(route.params.id==='orders'?"content.ui.orders":"c2c.nav.paymentAccounts") }}</div><button v-if="route.params.id==='accounts'" class="primary-button" @click="openModal('info',&quot;c2c.order.payoutAccountEmptyCta&quot;,{description:&quot;content.ui.thisDemoDoesNotCollectBankCardOrReal&quot;})">{{ $t("c2c.order.payoutAccountEmptyCta") }}</button></div><div v-else class="c2c-grid section-gap"><section class="card"><h2>{{ $t("c2c.quotes.title") }}</h2><div class="filter-row"><button v-for="c in [&quot;aiQuant.templates.filterAll&quot;,'ETH','USDC','BTC','USDT','SOL']" :class="{active:category===c}" @click="category=c">{{ $t(c) }}</button><label>{{ $t("assets.assetKind.fiat") }}<select><option :value="&quot;aiQuant.templates.filterAll&quot;">{{ $t("aiQuant.templates.filterAll") }}</option><option :value="&quot;USD&quot;">{{ $t("USD") }}</option></select></label></div><div class="two-cols"><button v-for="q in filteredQuotes" :key="q[0]" class="quote-card" :class="{selected:selected===q}" @click="selected=q"><span class="coin-label"><Coin :symbol="q[0]"/><strong>{{ $t(q[0]) }}{{ $t(" / USD") }}</strong></span><strong class="quote-price">{{ $t(fmt(q[1])) }} <small>{{ $t("USD") }}</small></strong><span class="mini-label">{{ $t("c2c.quotes.limitRange") }}{{ $t(fmt(q[2])) }}–{{ $t(fmt(q[3])) }} {{ $t(q[0]) }}</span><span class="tag-chip">{{ $t("c2c.accounts.form.accountTypeBank") }}</span></button></div></section><aside class="card"><div v-if="!selected" class="empty"><Icon name="hand-coins"/>{{ $t("c2c.order.selectPrompt") }}</div><form v-else class="form-stack" @submit.prevent="openModal('c2c',&quot;content.ui.confirmC2c&quot;+(route.params.id==='sell'?&quot;assets.convert.from&quot;:&quot;assets.convert.to&quot;),{name:selected[0]+'/USD',symbol:selected[0],min:selected[2],max:selected[3],amount})"><h2>{{ $t(route.params.id==='sell'?"assets.convert.from":"assets.convert.to") }} {{ $t(selected[0]) }}</h2><p class="metric">{{ $t(fmt(selected[1])) }} <small>{{ $t("USD") }}</small></p><label>{{ $t("aiQuant.quantFund.interestRecords.table.amount") }}<input v-model="amount" inputmode="decimal" :placeholder="$t(&quot;c2c.order.assetAmountPlaceholder&quot;)"/></label><div class="summary-line"><span class="muted">{{ $t("c2c.proof.paidAmount") }}</span><strong>{{ $t(fmt((Number(amount)||0)*selected[1])) }}{{ $t(" USD") }}</strong></div><button class="primary-button">{{ $t(route.params.id==='sell'?"assets.convert.from":"assets.convert.to") }} {{ $t(selected[0]) }}</button><p class="notice">{{ $t("content.ui.thisLocalDemoDoesNotCreateRealOrders") }}</p></form></aside></div></div></template>
<template v-else-if="section==='copytrade'"><div class="container copytrade"><p class="page-kicker">{{ $t("copytrade.page.subtitle") }}</p><h1 class="page-title">{{ $t("auth.registerComplete.actionCopyTrade.title") }}</h1><p class="page-desc">{{ $t("copytrade.page.description") }}</p><div class="copy-filters"><div class="record-tabs"><button v-for="t in [&quot;copytrade.tabs.leaderboard&quot;,&quot;copytrade.tabs.following&quot;,&quot;copytrade.tabs.myTrades&quot;]" :class="{active:activeTab===t}" @click="activeTab=t">{{ $t(t) }}</button></div><input v-model="query" :placeholder="$t(&quot;copytrade.filters.searchPlaceholder&quot;)" :aria-label="$t(&quot;copytrade.filters.searchPlaceholder&quot;)"/><button class="secondary-button" :aria-expanded="filters" @click="filters=!filters">{{ $t("copytrade.filters.show") }}</button></div><div v-if="filters" class="filter-row"><label>{{ $t("aiQuant.templates.fields.riskLevel") }}<select><option :value="&quot;aiQuant.templates.filterAll&quot;">{{ $t("aiQuant.templates.filterAll") }}</option><option :value="&quot;aiQuant.quantFund.riskLevel.LOW&quot;">{{ $t("aiQuant.quantFund.riskLevel.LOW") }}</option><option :value="&quot;aiQuant.quantFund.riskLevel.MEDIUM&quot;">{{ $t("aiQuant.quantFund.riskLevel.MEDIUM") }}</option><option :value="&quot;aiQuant.quantFund.riskLevel.HIGH&quot;">{{ $t("aiQuant.quantFund.riskLevel.HIGH") }}</option></select></label><label>{{ $t("aiQuant.templates.sortBy.label") }}<select><option :value="&quot;aiQuant.strategies.fields.returnPercent&quot;">{{ $t("aiQuant.strategies.fields.returnPercent") }}</option><option :value="&quot;copytrade.sort.followers&quot;">{{ $t("copytrade.sort.followers") }}</option><option :value="&quot;aiQuant.dailyStats.activeDays&quot;">{{ $t("aiQuant.dailyStats.activeDays") }}</option></select></label></div><div class="empty">{{ $t(query?"copytrade.empty.noSearchResults":activeTab==="copytrade.tabs.leaderboard"?"content.ui.noTradersAvailable":activeTab==="copytrade.tabs.following"?"content.ui.noFollowingYet":"copytrade.empty.noMyTrades") }}<p>{{ $t("copytrade.security.footer") }}</p></div></div></template>
<template v-else-if="['deposit','withdraw'].includes(section)"><div class="container section-pad"><div class="summary-line"><RouterLink class="muted" :to="path('/assets')">{{ $t("account.ui.back") }}</RouterLink><RouterLink class="muted" :to="path('/assets/records')">{{ $t("deposit.history.entry") }}</RouterLink></div><h1 class="page-title">{{ $t(section==='deposit'?"assets.deposit":"assets.typeWithdraw") }}</h1><p class="page-desc">{{ $t(section==='deposit'?"deposit.subtitle":"content.ui.selectAnAssetAndNetworkThenEnterTheDestination") }}</p><form class="form-stack section-gap" @submit.prevent="submitFunds"><label>{{ $t("assets.withdraw.coin") }}<select v-model="coin"><option :value="&quot;USDT&quot;">{{ $t("USDT") }}</option><option :value="&quot;USDC&quot;">{{ $t("USDC") }}</option><option :value="&quot;BTC&quot;">{{ $t("BTC") }}</option><option :value="&quot;ETH&quot;">{{ $t("ETH") }}</option></select></label><label>{{ $t("deposit.selectNetwork") }}<select v-model="network"><option :value="&quot;ETH&quot;">{{ $t("ETH") }}</option><option :value="&quot;TRON&quot;">{{ $t("TRON") }}</option><option :value="&quot;BTC&quot;">{{ $t("BTC") }}</option></select></label><div class="two-cols"><div class="form-stack"><p class="notice">{{ $t("content.ui.localDemoDoNotTransferToDemoAddressesOr") }}</p><template v-if="section==='deposit'"><label>{{ $t("deposit.depositAddress") }}<code class="card" style="overflow-wrap:anywhere">{{ $t("DEMO-ADDRESS-NOT-FOR-TRANSFER") }}</code></label></template><label v-else>{{ $t("assets.withdraw.address") }}<input v-model="address" :placeholder="$t(&quot;assets.withdraw.error.addressRequired&quot;)"/></label><label>{{ $t("deposit.voucher.amountLabel") }}<input v-model="amount" inputmode="decimal" :placeholder="$t(&quot;c2c.order.fiatAmountPlaceholder&quot;)"/></label><label v-if="section==='deposit'">{{ $t("deposit.voucher.txHashLabel") }}<input v-model="hash" :placeholder="$t(&quot;deposit.voucher.txHashPlaceholder&quot;)"/></label></div><label v-if="section==='deposit'" class="upload-area">{{ $t("deposit.voucher.screenshotLabel") }}<span class="card">{{ receipt||$t("deposit.voucher.screenshotHint") }}<input type="file" accept="image/png,image/jpeg" @change="receiptChange"/><small>{{ $t("content.ui.selectedLocallyFilesAreNotUploaded") }}</small></span></label></div><p v-if="message" role="status" class="notice">{{ $t(message) }}</p><button class="primary-button">{{ $t("content.ui.submitDemo") }}</button></form></div></template>
<template v-else><div class="container section-pad"><h1 class="page-title">{{section==='messages'?$t("common.announcements"):$t('common.notFound.title')}}</h1><div v-if="section==='messages'" class="card empty"><Icon name="mail"/>{{$t("content.ui.noAnnouncements")}}</div><RouterLink v-else class="green-link" :to="path('/')">{{$t('news.backToHome')}}</RouterLink></div></template>
</template>
<style scoped>.legal-page{max-width:960px;padding:64px 24px;margin:auto;line-height:1.85}.legal-page h1{font-size:2.25rem;margin-bottom:32px}.legal-page h2,.legal-page h3{margin:32px 0 16px}.legal-page p{color:#fff9;margin:16px 0;white-space:pre-line;overflow-wrap:anywhere}.news-detail>img{width:100%;border-radius:var(--nt-radius-panel);margin:32px 0}.news-detail h1{font-size:2.5rem;line-height:1.4}.c2c-grid{display:grid;grid-template-columns:2fr 1fr;gap:24px}.quote-card{display:grid;gap:20px;text-align:left;background:#ffffff04;border:1px solid #ffffff0b;border-radius:var(--nt-radius-panel);padding:24px}.quote-card.selected{border-color:var(--nt-accent);background:#a5ff4a06}.quote-price{font-size:1.625rem}.quote-price small{font-size:0.75rem;color:#fff8}.quote-card .tag-chip{width:max-content}.copytrade{max-width:1280px;padding:60px 32px;background:radial-gradient(ellipse at top,#a5ff4a08,transparent 60%)}.copy-filters{display:flex;align-items:center;gap:12px;margin-top:32px;border-bottom:1px solid #ffffff0b}.copy-filters .record-tabs{border:0;flex:1;padding-left:0}.copy-filters input{max-width:240px}.upload-area>span{min-height:270px;display:grid;align-content:center;gap:24px;text-align:center;border-style:dashed;background:#0c1017}.upload-area small{color:#fff6}.upload-area input{width:100%}.profile-settings{margin:40px 0}.profile-settings>div{padding:20px 0;border-top:1px solid #ffffff0a}.carousel-dots button{box-sizing:content-box;border:8px solid transparent;background-clip:padding-box}.charity-banner{background:#16191a}@media(max-width:900px){.c2c-grid{grid-template-columns:1fr}.copy-filters{flex-wrap:wrap;padding-bottom:16px}.copy-filters .record-tabs{flex-basis:100%}.copy-filters input{max-width:none;flex:1;min-width:0}}@media(max-width:600px){.news-detail h1{font-size:1.625rem}.copytrade{padding:40px 20px}.charity-banner h1{line-height:1.5}.c2c-grid .two-cols{grid-template-columns:1fr}.quote-price{font-size:1.5rem}.carousel-dots{gap:0}.upload-area>span{min-height:180px}}
</style>
